/// <summary>
/// Controller class for ER price list report
/// </summary>
public class AVAInventNonConformanceReportControllerCls extends ERFormatMappingRunBaseController
{
}

Method.Source:
/// <summary>
/// The main entrance of the controller
/// </summary>
/// <param name = "args">The arguments</param>
public static void main(Args args)
{
    if(!WMSParameters::find().AVAERNonConformanceFormat)
    {
        throw Error(strFmt("@NDX:NXANonConformanceReportError", "@SYS25197", "@SYS333869", "@SYS336190", "@SYS54502"));
    }

    AVAInventNonConformanceReportControllerCls operation;
    operation = new AVAInventNonConformanceReportControllerCls(
        classStr(AVAInventNonConformanceReportServiceCls),
        methodStr(AVAInventNonConformanceReportServiceCls, generateReport),
        SysOperationExecutionMode::Synchronous);

    AVAInventNonConformanceReportContractCls contract = operation.getDataContractObject();

    contract.initFromArgs(args);
    operation.startOperation();
}

/// <summary>
/// Gets caption of the dialog.
/// </summary>
/// <returns>Caption of the dialog</returns>
public ClassDescription defaultCaption()
{
    ClassDescription batchDescription;
    batchDescription = "@NDX:NXAInventNonConformance";
    return batchDescription;
}
